// th16_s6_b6: TH16 v1.00a Stage 6 BossCard3 (spell 78)
// source: st06bs.ecl.txt:1087-1198 (BossCard3), 1200-1276 (BossCard3_at)

const TIME_LIMIT: int = 3124;
const OPENING_BUFFER: int = 120;

// transcribe/th16/touhou-bullets.ecl (approved TH16 aliases, source=th16)
const TH16_FIREBALL_RED: int = 752;
const TH16_FIREBALL_YELLOW: int = 800;

// BossCard3_at EX records 2/3 (VELTIME), 4 (STEP a=1 b=1 c=1), 7 (VELTIME).
// record 0 ANIM and 1/6 BRIGHT are the omitted birth/visual stage; record 5
// SETSPRITE becomes set_sprite below. Source EX moves the bullet vector by
// delta*direction each tick, so VELTIME 1/2 are Cartesian accelerations.
xformdef B3_RISE(ay1: fx, ay2: fx, a2: int, d3: fx) {
    set_gravity(0fx, ay1);             // VELTIME a=120, r=1.8..2.2(E)/2.3..2.7(L), s=-pi/2
    wait(120);
    set_gravity(0fx, ay2);             // VELTIME a=400(E)/260(L), r=-1.0, s=-pi/2
    wait(a2);
    set_speed(0fx);                    // STEP boundary: logical speed := s = 0
    aim_player(0deg);                  // STEP c=1: re-query player at segment boundary
    set_sprite(TH16_FIREBALL_RED, 0);  // SETSPRITE a=25 color 0
    set_accel(d3);                     // VELTIME a=120, r=4(E)/6(L), s=keep current angle
    wait(120);
    set_accel(0fx);
}

// One BossCard3_at call: 30 bullets, one every per_wait frames, spawn x advancing by step.
sub burst(start_x: fx, step: fx, per_wait: int, base1: fx, a2: int, dive: fx) {
    var x: fx = start_x;
    for i in 0..30 {
        // same draw order as source: RANDF (speed), RANDF2 (veltime target), RANDF2 (angle)
        var u1: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
        var u2: fx = ((rand(65536) - 32768) as fx) / 32768;
        var u3: fx = ((rand(65536) - 32768) as fx) / 32768;
        var s0: fx = u1 * 1.2fx;                         // etSpeed: RANDF*1.2
        var r1: fx = base1 + u2 * 0.2fx;                 // pushed VELTIME target
        var off_deg: int = (u3 * 40fx) as int;           // RANDF2 * 0.6981317 rad
        var a0: angle = -90deg + (((off_deg * 65536) / 360) as angle);
        var d1: fx = (r1 - s0) / 120;                    // (r1 - current)/a
        var d2: fx = (0fx - 1fx - r1) / a2;              // (-1.0 - r1)/a
        var vx: fx = s0 * cos(a0);
        var vy: fx = s0 * sin(a0);
        // etOffsetAbs(x, 448) in world coordinates; ANIM birth stage keeps position -= 4*velocity
        _ = fire(TH16_FIREBALL_YELLOW, 0,
                 x - 4fx * vx, 448fx - 4fx * vy,
                 s0, a0,
                 B3_RISE(0fx - d1, 0fx - d2, a2, dive / 120), none);
        x = x + step;
        wait(per_wait);
    }
}

async sub burst_async(start_x: fx, step: fx, per_wait: int, base1: fx, a2: int, dive: fx) {
    burst(start_x, step, per_wait, base1, a2, dive);
}

async sub card_pattern() {
    // difficulty values pushed in BossCard3_1584 / BossCard3_at; ranks = [0, 3]
    var per_wait: int = 4;
    var base1: fx = 2.5fx;
    var a2: int = 260;
    var dive: fx = 6fx;
    var step: fx = 13fx;
    if global(GVAR_RANK) < RANK_LUNATIC {
        per_wait = 12;
        base1 = 2.0fx;
        a2 = 400;
        dive = 4fx;
        step = 26fx;
    }
    wait(60);   // source 1130: wait(60) after movePosTime
    wait(60);   // source 1138: wait(60), then $B = 1000
    for round in 0..1000 {
        spawn burst_async(192fx, 0fx - step, per_wait, base1, a2, dive);   // source 1160 async
        burst(0fx - 192fx, step, per_wait, base1, a2, dive);               // source 1178 sync
        wait(30);   // source 1188
    }
    loop { wait(1); }   // source 2368/2388 idle until interrupt
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(28fx);   // Boss() context setHurtbox(56,56)
    set_hitbox(25fx);    // Boss() context setHitbox(50,50)
    wait(OPENING_BUFFER);
    // source 1110-1125: zero velocity (spawned at rest), movePosTime(60,4,0,144);
    // moveLimit(0,144,240,64) never clamps because the boss stays at the box centre.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    spell_begin(0, 78, card_pattern, 3000, 0, 0, 0);   // source 1116-1122
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2500, 0, 0, 0, boss_main);   // Boss() lifeSet(2500), entry at (0,128)
    loop { wait(600); }
}
